#!/usr/bin/env bash
# Start (or restart) Airflow in standalone mode in the background.
#
#   bash scripts/start_airflow.sh          # start, wait until healthy
#   bash scripts/start_airflow.sh stop     # stop
#
# Airflow 3 exposes its health endpoint at /api/v2/monitor/health (not /health).
# On success the admin credentials generated by `standalone` are printed.
set -uo pipefail

PROJECT_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
source "$PROJECT_ROOT/scripts/env.sh"

LOG="$PROJECT_ROOT/logs_airflow.log"
PIDFILE="$PROJECT_ROOT/.airflow.pid"
ADMIN_PW_FILE="$AIRFLOW_HOME/standalone_admin_password.txt"
HEALTH_URL="http://localhost:$AIRFLOW_PORT/api/v2/monitor/health"

stop_airflow() {
  if [ -f "$PIDFILE" ] && kill -0 "$(cat "$PIDFILE")" 2>/dev/null; then
    echo "Stopping Airflow (pid $(cat "$PIDFILE")) ..."
    kill "$(cat "$PIDFILE")" 2>/dev/null
    for _ in $(seq 1 30); do
      kill -0 "$(cat "$PIDFILE")" 2>/dev/null || break
      sleep 1
    done
    kill -9 "$(cat "$PIDFILE")" 2>/dev/null
    echo "stopped"
  else
    echo "not running"
  fi
  rm -f "$PIDFILE"
}

if [ "${1:-start}" = "stop" ]; then
  stop_airflow
  exit 0
fi

stop_airflow
mkdir -p "$AIRFLOW_HOME"

echo "Initialising Airflow metadata DB in $AIRFLOW_HOME ..."
"$VENV/bin/airflow" db migrate >>"$LOG" 2>&1 || {
  echo "airflow db migrate FAILED - last 20 log lines:"; tail -20 "$LOG"; exit 1; }

echo "Starting 'airflow standalone' on port $AIRFLOW_PORT ..."
nohup "$VENV/bin/airflow" standalone >>"$LOG" 2>&1 &
echo $! > "$PIDFILE"
echo "  pid $(cat "$PIDFILE")   log -> $LOG"

for i in $(seq 1 120); do
  if [ "$(curl -s -o /dev/null -w '%{http_code}' "$HEALTH_URL")" = "200" ]; then
    echo "Airflow is UP after ${i}s"
    echo "  UI      -> http://localhost:$AIRFLOW_PORT"
    echo "  MLflow  -> $MLFLOW_TRACKING_URI"
    echo "  health  -> $(curl -s "$HEALTH_URL")"
    echo "  admin   -> $(cat "$ADMIN_PW_FILE" 2>/dev/null || echo 'see logs')"
    exit 0
  fi
  sleep 1
done

echo "Airflow did not become healthy within 120s. Last 40 log lines:"
tail -40 "$LOG"
exit 1